def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    out = [row[:] for row in grid]
    for top in range(rows - 4):
        for color in set(value for row in grid[top:] for value in row):
            solid = [grid[top][c] == color for c in range(cols)]
            for bottom in range(top, rows):
                if bottom > top:
                    solid = [solid[c] and grid[bottom][c] == color for c in range(cols)]
                if bottom - top + 1 < 5:
                    continue
                c = 0
                while c < cols:
                    if solid[c]:
                        left = c
                        while c < cols and solid[c]:
                            c += 1
                        if c - left >= 5:
                            for r in range(top, bottom + 1):
                                for x in range(left, c):
                                    out[r][x] = 4
                    else:
                        c += 1
    return out

