# Discover maximal uniform rectangular zones with dimensions >=3x5 or 5x3.
def max_rects(grid,minh=3,minw=3):
 H,W=len(grid),len(grid[0]); out=set()
 for top in range(H):
  for color in set(grid[top]):
   mask=[grid[top][c]==color for c in range(W)]
   for bot in range(top,H):
    if bot>top: mask=[mask[c] and grid[bot][c]==color for c in range(W)]
    if bot-top+1<minh: continue
    c=0
    while c<W:
     if mask[c]:
      left=c
      while c<W and mask[c]: c+=1
      if c-left>=minw: out.add((color,top,bot,left,c-1))
     else:c+=1
 return sorted(out,key=lambda x:(x[1],x[3],x[2],x[4]))
